using System.Data;using Microsoft.Data.SqlClient;using Microsoft.EntityFrameworkCore;using WhatsBiz.Application.Common.Exceptions;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Infrastructure.Persistence;
namespace WhatsBiz.Infrastructure.Purchases;
public sealed class PurchaseEngine(ApplicationDbContext db):IPurchaseEngine{public async Task<PurchasePostResult> Post(PurchasePostRequest r,CancellationToken token){await using var reader=await Execute("purchase.Purchase_Post",new[]{("@SupplierId",(object?)r.SupplierId),("@SupplierInvoiceNo",r.SupplierInvoiceNo),("@InvoiceDate",r.InvoiceDate),("@DueDate",r.DueDate),("@WarehouseId",r.WarehouseId),("@ItemsJson",r.ItemsJson),("@ExpensesJson",r.ExpensesJson),("@PaymentsJson",r.PaymentsJson),("@BillDiscount",r.BillDiscount),("@RoundOff",r.RoundOff),("@Remarks",r.Remarks),("@Status",r.Status),("@CreatedBy",r.User)},token);if(!await reader.ReadAsync(token))throw new InvalidOperationException("Purchase post returned no result.");return new(reader.GetGuid(reader.GetOrdinal("PurchaseInvoiceId")),reader.GetString(reader.GetOrdinal("InvoiceNumber")),reader.GetDecimal(reader.GetOrdinal("GrandTotal")),reader.GetDecimal(reader.GetOrdinal("PaidAmount")),reader.GetDecimal(reader.GetOrdinal("BalanceAmount")),reader.GetString(reader.GetOrdinal("Status")));}public async Task Pay(PurchasePaymentRequest r,CancellationToken token){await using var reader=await Execute("purchase.Purchase_AddPayment",new[]{("@PurchaseInvoiceId",(object?)r.PurchaseInvoiceId),("@MethodCode",r.MethodCode),("@Amount",r.Amount),("@ReferenceNumber",r.ReferenceNumber),("@CreatedBy",r.User)},token);await reader.ReadAsync(token);}public async Task Return(PurchaseReturnRequest r,CancellationToken token){await using var reader=await Execute("purchase.Purchase_Return",new[]{("@PurchaseInvoiceId",(object?)r.PurchaseInvoiceId),("@ItemsJson",r.ItemsJson),("@Reason",r.Reason),("@CreatedBy",r.User)},token);await reader.ReadAsync(token);}private async Task<SqlDataReader> Execute(string name,IReadOnlyCollection<(string Name,object? Value)> values,CancellationToken token){var connection=(SqlConnection)db.Database.GetDbConnection();if(connection.State!=ConnectionState.Open)await connection.OpenAsync(token);var command=connection.CreateCommand();command.CommandText=name;command.CommandType=CommandType.StoredProcedure;foreach(var x in values)command.Parameters.AddWithValue(x.Name,x.Value??DBNull.Value);try{return await command.ExecuteReaderAsync(CommandBehavior.CloseConnection,token);}catch(SqlException ex)when(ex.Number>=51200){await command.DisposeAsync();await connection.CloseAsync();throw new BusinessRuleException(ex.Message);}}}
